mod packet;mod linear;mod producer;mod verifier;
#[path="../triangular-witness/core.rs"]mod core;
#[path="../triangular-witness/cost.rs"]mod cost;
#[path="../canonical-root/root.rs"]mod root;
#[path="../triangular-witness/geometry.rs"]mod geometry;
use hec_native_ic::{counted,fp::Fp,poly::Poly,jac::Curve,instance::factor_base,rng::Rng};use packet::Context;
fn main(){counted::disable();let(mut accepts,mut rejects)=(0,0);for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&c);let pt=fb[0];let base=c.place(pt.0,pt.1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let k=1+rng.below(ell-1);let target=c.mul(&d,k);let context=Context{c:c.clone(),d,target,ell,sm};let mut last=None;for seed in 1..=3{let tr=core::solve(&c,pt,&d,&target,ell,sm,seed,true,true);if tr.answer.is_some(){last=Some(tr);break}}let tr=last.unwrap();let cover=producer::build(&context,&tr);assert_eq!(cover.k,k);assert!(verifier::verify(&context,&cover));let mut mutations=vec![];let mut b=cover.clone();b.branches.pop();mutations.push(b);let mut b=cover.clone();b.branches[1].0=b.branches[0].0;mutations.push(b);let mut b=cover.clone();b.branches[0].0=(b.branches[0].0+1)%ell;mutations.push(b);let mut b=cover.clone();b.context.target=c.add(&target,&d);mutations.push(b);let mut b=cover.clone();b.context.d=c.add(&d,&d);mutations.push(b);let mut b=cover.clone();b.context.ell+=2;mutations.push(b);let mut b=cover.clone();b.context.sm=(sm+1)%ell;mutations.push(b);let mut b=cover.clone();b.context.c.f.c[0]=(cc+1)%p;mutations.push(b);let mut b=cover.clone();b.z=1;mutations.push(b);let mut b=cover.clone();b.reps[0].1=(b.reps[0].1+1)%p;mutations.push(b);let mut b=cover.clone();b.primitives[0].points[0].1=(b.primitives[0].points[0].1+1)%p;mutations.push(b);let mut b=cover.clone();b.primitives[0].a=0;mutations.push(b);let mut b=cover.clone();b.primitives[0].t=p;mutations.push(b);let mut b=cover.clone();b.k=(k+1)%ell;mutations.push(b);let mut b=cover.clone();b.branches[0].1.w[0]=(b.branches[0].1.w[0]+1)%ell;mutations.push(b);let mut b=cover.clone();b.branches[0].1.excluded=!b.branches[0].1.excluded;mutations.push(b);let mut b=cover.clone();b.branches[0].1.w.pop();mutations.push(b);let mut b=cover.clone();b.branches[0].1.w[0]=ell;mutations.push(b);assert_eq!(mutations.len(),18);for b in mutations{assert!(!verifier::verify(&context,&b));rejects+=1;}accepts+=1;println!("COVER\tp={p}\tsm={sm}\tcase={case}\tpacket={cover:?}");}}}assert_eq!(accepts,12);assert_eq!(rejects,216);eprintln!("PASS bound_packets={accepts} mutations_rejected={rejects} full_root_geometry_binding_and_witness_checks=true runtime_action_character_calls=0 no_cost_claim=true independent_verification=false");}
